-- ========================================================
-- Nikhy RideCycle - PostgreSQL Schema & Demo Data Script
-- ========================================================
-- You can run this directly in pgAdmin Query Tool or via psql:
-- psql -U postgres -d nikhy_ridecycle_db -f seed_rides.sql
-- ========================================================

-- 1. Create table if not exists
CREATE TABLE IF NOT EXISTS "Rides" (
    "RideId" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "BookingId" bigint NULL,
    "PassengerId" bigint NOT NULL,
    "DriverId" bigint NULL,
    "PickupLocation" character varying(200) NOT NULL,
    "DestinationLocation" character varying(200) NOT NULL,
    "PickupLatitude" numeric(10, 7) NOT NULL,
    "PickupLongitude" numeric(10, 7) NOT NULL,
    "DestinationLatitude" numeric(10, 7) NOT NULL,
    "DestinationLongitude" numeric(10, 7) NOT NULL,
    "Status" character varying(30) NOT NULL,
    "Fare" numeric(10, 2) NOT NULL,
    "Distance" numeric(10, 2) NULL,
    "EstimatedDuration" integer NULL,
    "RequestedAt" timestamp with time zone NOT NULL,
    "AcceptedAt" timestamp with time zone NULL,
    "StartedAt" timestamp with time zone NULL,
    "CompletedAt" timestamp with time zone NULL,
    "CancelledAt" timestamp with time zone NULL,
    "CancellationReason" character varying(500) NULL,
    "CancelledBy" character varying(50) NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone NOT NULL
);

-- 2. Indexes for performance
CREATE INDEX IF NOT EXISTS "IX_Rides_PassengerId" ON "Rides" ("PassengerId");
CREATE INDEX IF NOT EXISTS "IX_Rides_DriverId" ON "Rides" ("DriverId");
CREATE INDEX IF NOT EXISTS "IX_Rides_Status" ON "Rides" ("Status");
CREATE INDEX IF NOT EXISTS "IX_Rides_CreatedAt" ON "Rides" ("CreatedAt");
CREATE INDEX IF NOT EXISTS "IX_Rides_Status_CreatedAt" ON "Rides" ("Status", "CreatedAt");

